  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What are the relative masses of protons, neutrons and electrons?', 'Proton 1, neutron 1, electron about 1/1840.', 3),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the atomic number?', 'The number of protons in the nucleus.', 4),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the mass number?', 'The total number of protons and neutrons in the nucleus.', 5),
