  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is nuclear fission?', 'Splitting a large nucleus into smaller nuclei, releasing energy and neutrons.', 30),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is density?', 'Mass per unit volume: ρ = m/V.', 1),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the unit of density?', 'kg/m³ (or g/cm³).', 2),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the density of a 200 g block with volume 100 cm³.', '200 ÷ 100 = 2 g/cm³.', 3),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'How can the density of an irregular object be found?', 'Measure its mass with a balance and its volume by displacement of water in a measuring cylinder.', 4),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the particle arrangement in a solid?', 'Particles are closely packed in a regular pattern, vibrating about fixed positions.', 5),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the particle arrangement in a liquid?', 'Particles are close together but randomly arranged and can move past each other.', 6),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the particle arrangement in a gas?', 'Particles are far apart, randomly arranged and move quickly in all directions.', 7),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Why are gases less dense than solids?', 'The particles are much further apart.', 8),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is internal energy?', 'The total kinetic and potential energy of all the particles in a system.', 9),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What happens to internal energy when a substance is heated?', 'It increases, either raising the temperature or changing the state.', 10),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is specific heat capacity?', 'The energy needed to raise the temperature of 1 kg of a substance by 1 °C.', 11),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the equation for specific heat capacity?', 'ΔQ = m × c × Δθ.', 12),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the energy needed to heat 2 kg of water by 10 °C (c = 4200 J/kg°C).', '2 × 4200 × 10 = 84,000 J.', 13),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is specific latent heat?', 'The energy needed to change the state of 1 kg of a substance without a change in temperature.', 14),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the equation for specific latent heat?', 'Q = m × L.', 15),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the specific latent heat of fusion?', 'The energy needed to change 1 kg from solid to liquid.', 16),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the specific latent heat of vaporisation?', 'The energy needed to change 1 kg from liquid to gas.', 17),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Why does temperature stay constant during a change of state?', 'The energy is used to break bonds between particles, not to increase kinetic energy.', 18),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is melting?', 'Changing from solid to liquid.', 19),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is evaporation?', 'Changing from liquid to gas at the surface of a liquid, below its boiling point.', 20),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is elastic deformation?', 'When an object returns to its original shape after the force is removed.', 21),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is inelastic (plastic) deformation?', 'When an object doesn''t return to its original shape after the force is removed.', 22),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is Hooke''s law?', 'The extension of a spring is directly proportional to the force applied, up to the limit of proportionality.', 23),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the equation for Hooke''s law?', 'F = k × x.', 24),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the spring constant?', 'The force needed to stretch a spring by 1 m, measured in N/m.', 25),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the force needed to stretch a spring with k = 50 N/m by 0.2 m.', '50 × 0.2 = 10 N.', 26),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the limit of proportionality?', 'The point beyond which extension is no longer proportional to force.', 27),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the energy stored in a stretched spring?', 'E = ½kx² (elastic potential energy).', 28),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the energy stored in a spring with k = 100 N/m stretched 0.1 m.', '½ × 100 × 0.1² = 0.5 J.', 29),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What does the gradient of a force–extension graph show?', 'The spring constant.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Physics' AND exam_board = 'OCR B' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
